import React, { useEffect, useState } from "react";
import axios from "axios";

const MyOrders = () => {
  const [orders, setOrders] = useState([]);

  useEffect(() => {
    const user = JSON.parse(localStorage.getItem("user"));

    if (!user) return;

    fetchOrders(user._id);
  }, []);

  const fetchOrders = async (userId) => {
    try {
      const res = await axios.get(`http://localhost:5000/my-orders/${userId}`);
      setOrders(res.data);
    } catch (err) {
      console.log("Error fetching orders", err);
    }
  };

  return (
    <div style={container}>
      <h2 style={heading}>My Orders</h2>

      {orders.length === 0 ? (
        <p style={{ textAlign: "center" }}>No approved orders yet.</p>
      ) : (
        orders.map((order) => (
          <div key={order._id} style={card}>
            <h3>Order Approved ✅</h3>
            <p><b>Order ID:</b> {order._id}</p>
            <p><b>Name:</b> {order.name}</p>
            <p><b>Address:</b> {order.address}</p>
            <p><b>Pincode:</b> {order.pincode}</p>
            <p><b>Payment:</b> {order.paymentMethod}</p>
            <p><b>Status:</b> Confirmed</p>
          </div>
        ))
      )}
    </div>
  );
};

const container = {
  maxWidth: "700px",
  margin: "40px auto",
  padding: "20px"
};

const heading = {
  textAlign: "center",
  marginBottom: "20px"
};

const card = {
  background: "#fff",
  padding: "20px",
  borderRadius: "15px",
  boxShadow: "0 8px 20px rgba(0,0,0,0.08)",
  marginBottom: "20px"
};

export default MyOrders;
